//! Frozen exact-container preflight and target workflow; no builds here.
use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},process::{Command,Stdio},io::Read};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn run(args:&[String],out:&Path){let log=fs::File::create(out).unwrap();let err=log.try_clone().unwrap();assert!(Command::new(&args[0]).args(&args[1..]).stdout(Stdio::from(log)).stderr(Stdio::from(err)).status().unwrap().success(),"command failed; see{}",out.display());}
fn state()->Value{let mut v=BTreeMap::new();for p in ["/proc/loadavg","/sys/fs/cgroup/cpu.stat","/sys/fs/cgroup/cpu.max","/sys/fs/cgroup/memory.max","/sys/fs/cgroup/memory.events","/sys/fs/cgroup/memory.swap.events","/sys/fs/cgroup/memory.swap.max"]{if let Ok(s)=fs::read_to_string(p){v.insert(p,s);}}json!(v)}
fn proofs(p:&Path,out:&mut Vec<std::path::PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();let p=e.path();if e.file_type().unwrap().is_dir(){proofs(&p,out)}else if p.extension().is_some_and(|x|x=="proof"){out.push(p)}}}
fn main(){let phase=std::env::args().nth(1).unwrap();assert!(phase=="preflight"||phase=="measure");let root=Path::new("/output");let dir=root.join(&phase);fs::create_dir(&dir).unwrap();let manifest=read("/lb/manifest.json");let mut pins:BTreeMap<String,String>=serde_json::from_value(manifest["container_pins"].clone()).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h,"container pin{p}");}let mut prior:BTreeSet<String>=serde_json::from_value(manifest["prior_proof_sha256"].clone()).unwrap();assert_eq!(prior.len(),5340);
 let mut env=manifest["environment"].clone();env["ZOPRO_CPU_LAGRANGE_DIR"]=json!("/output/lagrange-cache");env["ZOPRO_BASIS_KEY_DIR"]=json!("/lb-basis");let mut cases=Vec::new();for base in manifest["cases"].as_array().unwrap(){for workers in if phase=="preflight"{vec![4]}else if base["shape"]=="1x2"{vec![32,64,96]}else{vec![64,96]}{let mut c=base.clone();c["name"]=json!(format!("{}-w{workers}",base["shape"].as_str().unwrap()));c["workers"]=json!(workers);c["cpu_affinity"]=json!(format!("0-{}",workers-1));c["rounds"]=json!(if c["shape"]=="1x2"{31}else{17});c["profile_rounds"]=json!(51);cases.push(c);}}
 let modes=["accepted","off","on","aeglos"];let variants:Vec<_>=modes.iter().map(|engine|json!({"name":engine,"binary":"/usr/local/bin/lb-adapter","environment":{"ZOPRO_LB_ENGINE":engine}})).collect();save(dir.join("before.json"),&state());for(name,args)in[("lscpu.txt",vec![]),("topology.txt",vec!["-e=CPU,CORE,SOCKET,NODE"])]{let o=Command::new("lscpu").args(args).output().unwrap();assert!(o.status.success());fs::write(dir.join(name),o.stdout).unwrap();}
 if phase=="preflight"{assert_eq!(cases.len(),9);let mut steps=Vec::new();for c in &cases{let stem=Path::new(c["image"].as_str().unwrap()).file_stem().unwrap();for mode in modes{let name=format!("{}-{mode}",c["name"].as_str().unwrap());let proofroot=dir.join("proofs").join(&name);let proofdir=proofroot.join(stem);let mut env=env.clone();env["RAYON_NUM_THREADS"]=json!("4");env["ZOPRO_LB_ENGINE"]=json!(mode);steps.push(json!({"kind":"command","name":name,"argv":["taskset","-c","0-3","/usr/local/bin/lb-adapter",c["image"],c["request"],"1",proofdir],"environment":env,"timeout_seconds":600}));steps.push(json!({"kind":"command","name":format!("verify-{name}"),"argv":["/usr/local/bin/gnark-verify","/keys",proofroot,"/manifest/zopro-keys.lock"],"timeout_seconds":120}));}}
  save(dir.join("pins.json"),&json!(pins));save(dir.join("workflow.json"),&json!({"version":1,"source_pins":dir.join("pins.json"),"environment":{},"steps":steps}));run(&["/usr/local/bin/lb-xtask".into(),"workflow".into(),dir.join("workflow.json").display().to_string(),dir.join("workflow").display().to_string()],&dir.join("workflow.log"));let mut ps=Vec::new();proofs(&dir.join("proofs"),&mut ps);assert_eq!(ps.len(),36);let mut inventory=BTreeMap::new();for p in ps{assert_eq!(fs::metadata(&p).unwrap().len(),164);let h=hash(&p);assert!(prior.insert(h.clone()));inventory.insert(p.display().to_string(),h);let public=p.with_extension("public");let stem=p.parent().unwrap().file_name().unwrap();let c=cases.iter().find(|c|Path::new(c["image"].as_str().unwrap()).file_stem().unwrap()==stem).unwrap();assert_eq!(hash(&public),c["public_sha256"].as_str().unwrap());inventory.insert(public.display().to_string(),hash(public));}assert_eq!(prior.len(),5376);save(dir.join("proof-inventory.json"),&json!(inventory));save(dir.join("complete.json"),&json!({"status":"complete","sdk_requests":144,"distinct_gnark_exports":36,"prior_after":prior,"after":state()}));
 }else{assert_eq!(cases.len(),19);let receipt=read("/lb/preflight-complete.json");assert_eq!(receipt["status"],"complete");for h in receipt["new_proof_sha256"].as_array().unwrap(){assert!(prior.insert(h.as_str().unwrap().into()));}assert_eq!(prior.len(),5376);pins.insert("/lb/preflight-complete.json".into(),hash("/lb/preflight-complete.json"));let perf="/usr/lib/linux-tools/6.8.0-147-generic/perf";run(&[perf.into(),"stat".into(),"-e".into(),"cycles:u".into(),"--".into(),"/bin/true".into()],&dir.join("perf-availability.log"));
  let config=json!({"version":1,"blocks":3,"profile_blocks":1,"profile_cases":["1x2-w32","1x2-w96"],"command":["{binary}","{image}","{request}","{rounds}","{proof_dir}/{stem}"],"variants":variants,"cases":cases,"pins":pins,"prior_proof_sha256":prior,"verifier":["/usr/local/bin/gnark-verify","/keys","{proof_dir}","/manifest/zopro-keys.lock"],"profile_environment":{"ZOPRO_BENCH_PERF_CTL":"{control}","ZOPRO_BENCH_PERF_ACK":"{ack}"},"environment":env,"checks":[],"child_prefix":[],"perf_prefix":[],"perf":perf,"frequency_hz":199,"monotonic_clock":true,"symbol_categories":manifest["symbol_categories"],"timeout_seconds":600});save(dir.join("config.json"),&config);run(&["/usr/local/bin/lb-xtask".into(),"perf".into(),dir.join("config.json").display().to_string(),dir.join("performance").display().to_string()],&dir.join("workflow.log"));let rows=read(dir.join("performance/rows.json"));assert_eq!(rows.as_array().unwrap().len(),236);let sdk:usize=rows.as_array().unwrap().iter().map(|r|r["samples_ms"].as_array().unwrap().len()+3).sum();assert_eq!(sdk,5496);save(dir.join("complete.json"),&json!({"status":"complete","sdk_requests":sdk,"distinct_gnark_exports":236,"after":state()}));
 }println!("{phase} complete");}
